                $update=$pdo->prepare('UPDATE ride_bookings SET status=? WHERE id=? AND status=\'Pending\''); $update->execute([$status,$bookingId]); $pdo->commit(); notify($pdo,(int)$booking['passenger_id'],'Your booking was '.$status.'.'); flash('Booking '.$status.'.'); redirect('dashboard');
