            case 'cancel_ride':
                $user=require_login();$rideId=(int)($_POST['ride_id']??0);$pdo->beginTransaction();$lock=$pdo->prepare("SELECT id FROM rides WHERE id=? AND driver_id=? AND status='Open' FOR UPDATE");$lock->execute([$rideId,$user['id']]);if(!$lock->fetch())throw new RuntimeException('This ride can no longer be cancelled.');$notify=$pdo->prepare("SELECT passenger_id FROM ride_bookings WHERE ride_id=? AND status IN ('Pending','Confirmed') FOR UPDATE");$notify->execute([$rideId]);$passengers=$notify->fetchAll();$pdo->prepare("UPDATE rides SET status='Cancelled' WHERE id=?")->execute([$rideId]);$pdo->prepare("UPDATE ride_bookings SET status='Cancelled' WHERE ride_id=? AND status IN ('Pending','Confirmed')")->execute([$rideId]);$pdo->commit();foreach($passengers as $row)notify($pdo,(int)$row['passenger_id'],'A ride you booked was cancelled by its driver.');flash('Ride cancelled and riders notified.');redirect('dashboard');
