            case 'message':
                $user=require_login(); $booking=(int)($_POST['booking_id']??0); $body=$text('body',2000); if (!$body) throw new RuntimeException('Write a message first.');
                $stmt=$pdo->prepare("SELECT b.id FROM ride_bookings b JOIN rides r ON r.id=b.ride_id WHERE b.id=? AND b.status IN ('Confirmed','Completed') AND (b.passenger_id=? OR r.driver_id=?)"); $stmt->execute([$booking,$user['id'],$user['id']]); if (!$stmt->fetch()) throw new RuntimeException('Messages are available to riders with confirmed or completed bookings.');
                $pdo->prepare('INSERT INTO chat_messages (booking_id,sender_id,body) VALUES (?,?,?)')->execute([$booking,$user['id'],$body]); flash('Message sent.'); header('Location: index.php?page=chat&booking='.$booking); exit;
            case 'review':
                $user=require_login(); $bookingId=(int)($_POST['booking_id']??0); $rating=(int)($_POST['rating']??0); $comment=$text('comment',1000);
                if ($rating<1 || $rating>5) throw new RuntimeException('Choose a rating from 1 to 5.');
                $stmt=$pdo->prepare("SELECT r.id ride_id,r.driver_id,b.passenger_id FROM rides r JOIN ride_bookings b ON b.ride_id=r.id WHERE b.id=? AND r.status='Completed' AND b.status='Completed' AND (b.passenger_id=? OR r.driver_id=?)"); $stmt->execute([$bookingId,$user['id'],$user['id']]); $parties=$stmt->fetch(); if (!$parties) throw new RuntimeException('Only participants in a completed ride may review.'); $target=(int)$parties['driver_id']===(int)$user['id']?(int)$parties['passenger_id']:(int)$parties['driver_id'];
