            case 'profile':
                $user=require_login(); $name=$text('name',100); $phone=$text('phone',30); if (!$name) throw new RuntimeException('Name is required.'); $photo=$user['profile_photo']??null;
                if(isset($_FILES['profile_photo'])&&$_FILES['profile_photo']['error']!==UPLOAD_ERR_NO_FILE){$file=$_FILES['profile_photo'];if($file['error']!==UPLOAD_ERR_OK||$file['size']>2*1024*1024)throw new RuntimeException('Profile image must be a valid image under 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime])||!getimagesize($file['tmp_name']))throw new RuntimeException('Upload a JPEG, PNG or WebP image.');$directory=dirname(__DIR__).'/uploads';if(!is_dir($directory))mkdir($directory,0755,true);$filename=bin2hex(random_bytes(16)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],$directory.'/'.$filename))throw new RuntimeException('Could not store the profile image.');$photo='uploads/'.$filename;}
                $pdo->prepare('UPDATE users SET name=?,phone=?,profile_photo=? WHERE id=?')->execute([$name,$phone,$photo,$user['id']]); $_SESSION['user']['name']=$name;$_SESSION['user']['phone']=$phone;$_SESSION['user']['profile_photo']=$photo; flash('Profile updated.'); redirect('profile');
            case 'change_password':
                $user=require_login();$old=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$stmt=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$stmt->execute([$user['id']]);if(!password_verify($old,(string)$stmt->fetchColumn())||strlen($new)<10)throw new RuntimeException('Current password is incorrect, or the new password is shorter than 10 characters.');$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$user['id']]);flash('Password changed.');redirect('profile');
            case 'support':
                $user=current_user(); $email=$text('email',190); $subject=$text('subject',160); $body=$text('body',3000); $kind=$text('kind',30);
                if (!$subject || !$body || (!$user && !filter_var($email,FILTER_VALIDATE_EMAIL)) || !in_array($kind,['Complaint','User report','Ride report','Emergency report','Support'],true)) throw new RuntimeException('Complete the contact, subject and message fields.');
                $stmt=$pdo->prepare('INSERT INTO complaints (user_id,contact_email,kind,subject,body) VALUES (?,?,?,?,?)'); $stmt->execute([$user['id']??null,$user['email']??$email,$kind,$subject,$body]); if($kind==='Emergency report')$pdo->prepare('INSERT INTO emergency_reports (user_id,details) VALUES (?,?)')->execute([$user['id']??null,$subject."\n\n".$body]); flash('Your report was sent to the MAPIDO support team. This form does not contact emergency services.'); redirect('support');
            case 'resolve_complaint':
                require_admin(); $pdo->prepare("UPDATE complaints SET status='Resolved',resolved_at=NOW() WHERE id=? AND status='Open'")->execute([(int)($_POST['complaint_id']??0)]); flash('Complaint marked resolved.'); redirect('admin');
