                require_admin();$rideId=(int)($_POST['ride_id']??0);$pdo->beginTransaction();$stmt=$pdo->prepare("SELECT id FROM rides WHERE id=? AND status='Open' FOR UPDATE");$stmt->execute([$rideId]);if(!$stmt->fetch())throw new RuntimeException('This ride is not open.');$stmt=$pdo->prepare("SELECT passenger_id FROM ride_bookings WHERE ride_id=? AND status IN ('Pending','Confirmed')");$stmt->execute([$rideId]);$passengers=$stmt->fetchAll();$pdo->prepare("UPDATE rides SET status='Cancelled' WHERE id=?")->execute([$rideId]);$pdo->prepare("UPDATE ride_bookings SET status='Cancelled' WHERE ride_id=? AND status IN ('Pending','Confirmed')")->execute([$rideId]);$pdo->commit();foreach($passengers as $passenger)notify($pdo,(int)$passenger['passenger_id'],'A MAPIDO administrator cancelled a ride you had booked.');flash('Ride cancelled and affected passengers notified.');redirect('admin');
