function page_data(PDO $pdo, string $page): array {
    $data=['title'=>ucfirst($page)]; $user=current_user();
    if ($page==='find') {
        $origin=trim((string)($_GET['origin']??'')); $destination=trim((string)($_GET['destination']??'')); $date=(string)($_GET['date']??'');$timeAfter=(string)($_GET['time_after']??'');$minimumSeats=max(1,min(8,(int)($_GET['min_seats']??1)));$maxContribution=(string)($_GET['max_contribution']??'');
        $seatCount="(SELECT COALESCE(SUM(b.seats),0) FROM ride_bookings b WHERE b.ride_id=r.id AND b.status='Confirmed')";
        $sql="SELECT r.*,u.name driver_name,v.model vehicle_model,v.registration_number,COALESCE(rv.rating,0) rating,(SELECT GROUP_CONCAT(label ORDER BY sequence_no SEPARATOR ' · ') FROM pickup_points WHERE ride_id=r.id) pickup_points,(r.total_seats-$seatCount) seats_left FROM rides r JOIN users u ON u.id=r.driver_id LEFT JOIN vehicles v ON v.id=r.vehicle_id LEFT JOIN (SELECT reviewed_user_id,AVG(rating) rating FROM reviews GROUP BY reviewed_user_id) rv ON rv.reviewed_user_id=u.id WHERE r.status='Open' AND r.travel_date>=CURDATE() AND u.is_suspended=0 AND (r.total_seats-$seatCount)>=?"; $params=[$minimumSeats];
        if($origin!==''){$sql.=' AND r.origin LIKE ?';$params[]='%'.$origin.'%';} if($destination!==''){$sql.=' AND r.destination LIKE ?';$params[]='%'.$destination.'%';} if(valid_date($date)){$sql.=' AND r.travel_date=?';$params[]=$date;} if(preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$timeAfter)){$sql.=' AND r.departure_time>=?';$params[]=$timeAfter.':00';} if($maxContribution!==''&&is_numeric($maxContribution)&&(float)$maxContribution>=0){$sql.=' AND r.estimated_cost/r.total_seats<=?';$params[]=(float)$maxContribution;}$sql.=' ORDER BY r.travel_date,r.departure_time LIMIT 50';$stmt=$pdo->prepare($sql);$stmt->execute($params);$data['rides']=$stmt->fetchAll();$data['origin']=$origin;$data['destination']=$destination;$data['date']=$date;$data['time_after']=$timeAfter;$data['min_seats']=$minimumSeats;$data['max_contribution']=$maxContribution;
    }
    if ($page==='dashboard' && $user) {
        $stmt=$pdo->prepare("SELECT b.*,r.origin,r.destination,r.travel_date,r.departure_time,r.driver_id,r.total_seats,u.name passenger_name FROM ride_bookings b JOIN rides r ON r.id=b.ride_id JOIN users u ON u.id=b.passenger_id WHERE (r.driver_id=? OR b.passenger_id=?) ORDER BY r.travel_date DESC,r.departure_time DESC LIMIT 40");$stmt->execute([$user['id'],$user['id']]);$data['bookings']=$stmt->fetchAll();
        $stmt=$pdo->prepare("SELECT r.*, (r.total_seats-COALESCE((SELECT SUM(b.seats) FROM ride_bookings b WHERE b.ride_id=r.id AND b.status='Confirmed'),0)) seats_left,(SELECT GROUP_CONCAT(label ORDER BY sequence_no SEPARATOR '\n') FROM pickup_points WHERE ride_id=r.id) pickup_points FROM rides r WHERE r.driver_id=? ORDER BY r.travel_date DESC LIMIT 20");$stmt->execute([$user['id']]);$data['rides']=$stmt->fetchAll();
        $stmt=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 8');$stmt->execute([$user['id']]);$data['notifications']=$stmt->fetchAll();
    }
    if($page==='bookings' && $user){$stmt=$pdo->prepare("SELECT b.*,r.origin,r.destination,r.travel_date,r.departure_time,r.driver_id,d.name driver_name,p.name passenger_name FROM ride_bookings b JOIN rides r ON r.id=b.ride_id JOIN users d ON d.id=r.driver_id JOIN users p ON p.id=b.passenger_id WHERE b.passenger_id=? OR r.driver_id=? ORDER BY r.travel_date DESC");$stmt->execute([$user['id'],$user['id']]);$data['bookings']=$stmt->fetchAll();}
    if($page==='chat' && $user){$stmt=$pdo->prepare("SELECT b.id booking_id,r.origin,r.destination,r.travel_date,CASE WHEN r.driver_id=? THEN p.name ELSE d.name END other_name,MAX(m.created_at) last_message,SUM(CASE WHEN m.sender_id<>? AND m.read_at IS NULL THEN 1 ELSE 0 END) unread_count FROM ride_bookings b JOIN rides r ON r.id=b.ride_id JOIN users d ON d.id=r.driver_id JOIN users p ON p.id=b.passenger_id LEFT JOIN chat_messages m ON m.booking_id=b.id WHERE b.status IN ('Confirmed','Completed') AND (r.driver_id=? OR b.passenger_id=?) GROUP BY b.id ORDER BY last_message DESC");$stmt->execute([$user['id'],$user['id'],$user['id'],$user['id']]);$data['conversations']=$stmt->fetchAll();$chosen=(int)($_GET['booking']??($data['conversations'][0]['booking_id']??0));$check=$pdo->prepare("SELECT b.id FROM ride_bookings b JOIN rides r ON r.id=b.ride_id WHERE b.id=? AND b.status IN ('Confirmed','Completed') AND (r.driver_id=? OR b.passenger_id=?)");$check->execute([$chosen,$user['id'],$user['id']]);if($check->fetch()){$pdo->prepare('UPDATE chat_messages SET read_at=NOW() WHERE booking_id=? AND sender_id<>? AND read_at IS NULL')->execute([$chosen,$user['id']]);$stmt=$pdo->prepare('SELECT m.*,u.name sender_name FROM chat_messages m JOIN users u ON u.id=m.sender_id WHERE m.booking_id=? ORDER BY m.created_at');$stmt->execute([$chosen]);$data['messages']=$stmt->fetchAll();$data['chosen']=$chosen;}}
    if($page==='profile' && $user){$stmt=$pdo->prepare("SELECT rv.*,u.name reviewer_name,r.origin,r.destination FROM reviews rv JOIN users u ON u.id=rv.reviewer_id JOIN rides r ON r.id=rv.ride_id WHERE rv.reviewed_user_id=? ORDER BY rv.created_at DESC");$stmt->execute([$user['id']]);$data['reviews']=$stmt->fetchAll();}
    if($page==='admin' && $user && $user['role']==='admin'){$data['stats']=['users'=>(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'rides'=>(int)$pdo->query('SELECT COUNT(*) FROM rides')->fetchColumn(),'bookings'=>(int)$pdo->query('SELECT COUNT(*) FROM ride_bookings')->fetchColumn()];$data['users']=$pdo->query('SELECT id,name,email,role,is_suspended,created_at FROM users ORDER BY created_at DESC LIMIT 100')->fetchAll();$data['complaints']=$pdo->query('SELECT c.*,u.name user_name FROM complaints c LEFT JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC LIMIT 100')->fetchAll();$data['reported_reviews']=$pdo->query('SELECT rv.id,rv.comment,rv.rating,rv.created_at,u.name reviewer_name,t.name target_name,r.origin,r.destination FROM reviews rv JOIN users u ON u.id=rv.reviewer_id JOIN users t ON t.id=rv.reviewed_user_id JOIN rides r ON r.id=rv.ride_id WHERE rv.is_reported=1 ORDER BY rv.created_at DESC LIMIT 100')->fetchAll();$data['admin_rides']=$pdo->query('SELECT r.id,r.origin,r.destination,r.travel_date,r.status,u.name driver_name FROM rides r JOIN users u ON u.id=r.driver_id ORDER BY r.created_at DESC LIMIT 100')->fetchAll();$data['admin_bookings']=$pdo->query('SELECT b.id,b.status,b.seats,r.origin,r.destination,p.name passenger_name,d.name driver_name FROM ride_bookings b JOIN rides r ON r.id=b.ride_id JOIN users p ON p.id=b.passenger_id JOIN users d ON d.id=r.driver_id ORDER BY b.created_at DESC LIMIT 100')->fetchAll();$data['emergency_reports']=$pdo->query('SELECT er.*,u.name user_name FROM emergency_reports er LEFT JOIN users u ON u.id=er.user_id ORDER BY er.created_at DESC LIMIT 100')->fetchAll();}
    return $data;
}